import type { Context } from '@deepseek-ai/cordis'
import type { Session, SessionEvent } from '@deepseek-ai/dsh-session'
import type { WebRoute } from '@deepseek-ai/dsh-host-webserver'

export const PET_ACTIVITY_API_PATH = '/api/ui-enhancer/pet-state'
export const PET_ACTIVITY_SESSION_LIMIT = 8
export const PET_COMPLETION_EVENT_LIMIT = 128
export const PET_SETTLED_PHASE_TTL_MS = 6_000
export const PET_SESSION_DETAIL_MAX = 200

export type PetActivityPhase = 'idle' | 'waiting' | 'thinking' | 'tool' | 'review' | 'done' | 'failed'

export interface PetActivitySessionView {
  sessionId: string
  phase: PetActivityPhase
  bubble: string
  /** Recent conversation detail: tool invocation or reply snippet. */
  detail: string
  updatedAt: number
}

export interface PetActivityView {
  phase: PetActivityPhase
  bubble: string
  sessions: PetActivitySessionView[]
  /** Oldest to newest; IDs stay stable across polls for client-side deduplication. */
  completedEventIds: string[]
}

interface SessionActivity {
  sessionId: string
  topLevel: boolean
  phase: PetActivityPhase
  bubble: string
  detail: string
  updatedAt: number
  activeTools: Set<string>
  stepHadFailure: boolean
}

function compactToolName(value: string): string {
  const compact = value.replace(/\s+/g, ' ').trim() || '工具'
  return compact.length <= 24 ? compact : `${compact.slice(0, 21)}...`
}

/** Append one text delta to the trailing detail window. */
function appendDetail(previous: string, delta: string): string {
  const combined = (previous + delta).replace(/\s+/g, ' ').trim()
  if (combined.length <= PET_SESSION_DETAIL_MAX) return combined
  return combined.slice(combined.length - PET_SESSION_DETAIL_MAX)
}

/** Detail line for a tool call: compact name plus a short argument snippet. */
function toolDetail(name: string, rawArguments: string): string {
  const compact = compactToolName(name)
  const argumentsSnippet = rawArguments.replace(/\s+/g, ' ').trim().slice(0, 80)
  return argumentsSnippet === '' ? `调用 ${compact}` : `调用 ${compact} · ${argumentsSnippet}`
}

function isSettled(activity: SessionActivity, nowMs: number): boolean {
  if (activity.phase === 'idle') return true
  return (activity.phase === 'done' || activity.phase === 'failed')
    && nowMs - activity.updatedAt >= PET_SETTLED_PHASE_TTL_MS
}

/** In-memory projection of official Harness session events for the desktop companion. */
export class PetActivityTracker {
  private readonly activity = new Map<string, SessionActivity>()
  private readonly completedEventIds: string[] = []
  private readonly completedEventSet = new Set<string>()

  accept(session: Session, event: SessionEvent, nowMs = Date.now()): void {
    switch (event.type) {
      case 'turn/start': {
        const activity = this.activityOf(session, nowMs)
        activity.activeTools.clear()
        activity.stepHadFailure = false
        activity.detail = ''
        this.commit(activity, 'waiting', '准备开始', nowMs)
        break
      }
      case 'step/start': {
        const activity = this.activityOf(session, nowMs)
        activity.activeTools.clear()
        activity.stepHadFailure = false
        activity.detail = ''
        this.commit(activity, 'waiting', '等待模型响应', nowMs)
        break
      }
      case 'assistant/chunk': {
        if (event.data.chunk.type === 'reasoning-delta' && event.data.chunk.text.length > 0) {
          this.commit(this.activityOf(session, nowMs), 'thinking', '正在思考', nowMs)
        } else if (event.data.chunk.type === 'text-delta' && event.data.chunk.text.length > 0) {
          const activity = this.activityOf(session, nowMs)
          // A tool line followed by prose starts a fresh run of text detail.
          const previous = activity.detail.startsWith('调用 ') ? '' : activity.detail
          activity.detail = appendDetail(previous, event.data.chunk.text)
          this.commit(activity, 'review', '整理回复中', nowMs)
        }
        break
      }
      case 'assistant/message':
        this.commit(this.activityOf(session, nowMs), 'review', '整理回复中', nowMs)
        break
      case 'tool/call': {
        const activity = this.activityOf(session, nowMs)
        activity.activeTools.add(String(event.data.callId))
        activity.detail = toolDetail(event.data.name, event.data.arguments)
        this.commit(activity, 'tool', `正在使用 ${compactToolName(event.data.name)}`, nowMs)
        break
      }
      case 'tool/result': {
        const activity = this.activityOf(session, nowMs)
        activity.activeTools.delete(String(event.data.message.source.callId))
        activity.stepHadFailure ||= event.data.error !== undefined
          || event.data.message.content[0]?.isError === true
        if (activity.activeTools.size > 0) {
          this.commit(activity, 'tool', `还有 ${activity.activeTools.size} 个工具运行中`, nowMs)
        } else if (activity.stepHadFailure) {
          this.commit(activity, 'failed', '工具执行失败', nowMs)
        } else {
          this.commit(activity, 'thinking', '处理工具结果', nowMs)
        }
        break
      }
      case 'turn/end': {
        const activity = this.activityOf(session, nowMs)
        activity.activeTools.clear()
        switch (event.data.reason.kind) {
          case 'completed':
            if (activity.topLevel) {
              this.rememberCompletion(`${String(session.id)}:${event.data.turn}`)
            }
            this.commit(activity, 'done', '完成啦', nowMs)
            break
          case 'error':
            this.commit(activity, 'failed', '执行失败', nowMs)
            break
          case 'max-tokens':
            this.commit(activity, 'failed', '达到输出上限', nowMs)
            break
          case 'interrupted':
            this.commit(activity, 'failed', '执行意外中断', nowMs)
            break
          case 'blocked':
            this.commit(activity, 'waiting', '等待继续', nowMs)
            break
          case 'aborted':
            this.commit(activity, 'idle', '', nowMs)
            break
          default:
            this.commit(activity, 'idle', '', nowMs)
        }
        break
      }
      default:
        break
    }
  }

  forget(session: Session): void {
    this.activity.delete(String(session.id))
  }

  snapshot(nowMs = Date.now()): PetActivityView {
    const current = [...this.activity.values()]
      .reverse()
      .filter((entry) => !isSettled(entry, nowMs))
    const display = current[0]
    const sessions = current
      .filter((entry) => entry.topLevel && entry.bubble !== '')
      .slice(0, PET_ACTIVITY_SESSION_LIMIT)
      .map(({ sessionId, phase, bubble, detail, updatedAt }) => ({ sessionId, phase, bubble, detail, updatedAt }))
    return {
      phase: display?.phase ?? 'idle',
      bubble: display?.bubble ?? '',
      sessions,
      completedEventIds: [...this.completedEventIds],
    }
  }

  private activityOf(session: Session, nowMs: number): SessionActivity {
    const sessionId = String(session.id)
    let activity = this.activity.get(sessionId)
    if (activity === undefined) {
      activity = {
        sessionId,
        topLevel: session.header.origin !== 'subagent',
        phase: 'idle',
        bubble: '',
        detail: '',
        updatedAt: nowMs,
        activeTools: new Set(),
        stepHadFailure: false,
      }
    } else {
      activity.topLevel = session.header.origin !== 'subagent'
    }
    return activity
  }

  private commit(
    activity: SessionActivity,
    phase: PetActivityPhase,
    bubble: string,
    nowMs: number,
  ): void {
    activity.phase = phase
    activity.bubble = bubble
    activity.updatedAt = nowMs
    this.activity.delete(activity.sessionId)
    this.activity.set(activity.sessionId, activity)
    while (this.activity.size > PET_ACTIVITY_SESSION_LIMIT) {
      const oldest = this.activity.keys().next().value
      if (oldest === undefined) break
      this.activity.delete(oldest)
    }
  }

  private rememberCompletion(id: string): void {
    if (this.completedEventSet.has(id)) return
    this.completedEventIds.push(id)
    this.completedEventSet.add(id)
    while (this.completedEventIds.length > PET_COMPLETION_EVENT_LIMIT) {
      const oldest = this.completedEventIds.shift()
      if (oldest !== undefined) this.completedEventSet.delete(oldest)
    }
  }
}

function respondJson(res: ServerResponse, body: PetActivityView): void {
  const payload = JSON.stringify(body)
  res.writeHead(200, {
    'content-type': 'application/json; charset=utf-8',
    'content-length': Buffer.byteLength(payload),
    'cache-control': 'no-store',
    'x-content-type-options': 'nosniff',
  })
  res.end(payload)
}

/** Mount the event projection and its plugin-owned, read-only browser route. */
export function registerPetActivity(ctx: Context): () => void {
  const tracker = new PetActivityTracker()
  const route: WebRoute = {
    kind: 'exact',
    path: PET_ACTIVITY_API_PATH,
    handler: (req: IncomingMessage, res: ServerResponse): void => {
      if (req.method !== 'GET') {
        res.writeHead(405, { allow: 'GET' })
        res.end()
        return
      }
      respondJson(res, tracker.snapshot())
    },
  }
  const disposers = [
    ctx.on('session/event', (session, event) => tracker.accept(session, event)),
    ctx.on('session/disposed', (session) => tracker.forget(session)),
    ctx.webServer.register(route),
  ]
  return () => {
    for (const dispose of disposers.reverse()) dispose()
  }
}
