  ClientContext,
  ObservableSnapshot,
  SessionId,
  SessionListState,
} from '@deepseek-ai/dsh-client-runtime/client'
import type {
  InputTriggerCandidate,
  InputTriggerSource,
  ReferenceCodec,
} from '@deepseek-ai/dsh-client-ui-input-trigger/client'
import { listWorkspaceFiles, searchWorkspaceFiles } from './api.ts'

interface FileReference {
  root: string
  path: string
}

const FILE_SOURCE_NAME = 'Files'

function encodeReference(reference: FileReference): string {
  return JSON.stringify(reference)
}

function decodeReference(value: string): FileReference | undefined {
  try {
    const parsed = JSON.parse(value) as Partial<FileReference>
    if (typeof parsed.root !== 'string' || typeof parsed.path !== 'string') return undefined
    return { root: parsed.root, path: parsed.path }
  } catch {
    return undefined
  }
}

function joinWorkspacePath(root: string, path: string): string {
  const separator = root.includes('\\') && !root.includes('/') ? '\\' : '/'
  return `${root.replace(/[\\/]+$/, '')}${separator}${path.replace(/^[\\/]+/, '').replace(/[\\/]/g, separator)}`
}

function escapeAttribute(value: string): string {
  return value
    .replaceAll('&', '&amp;')
    .replaceAll('"', '&quot;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
}

export const fileReferenceCodec: ReferenceCodec = {
  clipboardText(ref) {
    const reference = decodeReference(ref)
    return reference === undefined ? '@file' : `@${reference.path}`
  },
  async serialize(ref) {
    const reference = decodeReference(ref)
    if (reference === undefined) return '<workspace-file path="unknown" />'
    const absolutePath = joinWorkspacePath(reference.root, reference.path)
    // Deliberately path-only. The model may read the file when needed without
    // silently expanding a large document into every submitted prompt.
    return `<workspace-file path="${escapeAttribute(absolutePath)}" />`
  },
}

function rootForSession(ctx: ClientContext, sessionId: SessionId): string | undefined {
  // Cordis itself also has a lifecycle `sessions` member in its base types.
  // The web composition installs the DSH runtime face here at runtime; keep
  // this read explicitly narrowed to that public contract.
  const sessions = ctx.sessions as unknown as { list: ObservableSnapshot<SessionListState> }
  return sessions.list.getSnapshot().byId[sessionId]?.cwd
}

/** Official @ pipeline source for workspace-relative file references. */
export function createFileTriggerSource(ctx: ClientContext): InputTriggerSource {
  return {
    trigger: '@',
    // rc.6 renders an unknown source name verbatim as the menu group title.
    name: FILE_SOURCE_NAME,
    order: 10,
    codec: fileReferenceCodec,
    async candidates(session, request): Promise<readonly InputTriggerCandidate[]> {
      const root = rootForSession(ctx, session.sessionId)
      if (root === undefined || root === '') return []
      const query = request.query.trim()
      const hits = query === ''
        ? (await listWorkspaceFiles(root, request.signal)).entries
          .filter((entry) => entry.kind === 'file')
          .slice(0, 24)
        : (await searchWorkspaceFiles(root, query, request.signal)).hits
          .filter((entry) => entry.kind === 'file')
      return hits.map((hit) => {
        return {
          name: hit.path,
          description: document.documentElement.lang.startsWith('zh') ? '工作区文件' : 'Workspace file',
          hint: '@file',
        }
      })
    },
    onPick(pick) {
      const root = rootForSession(ctx, pick.session.sessionId)
      const reference = root === undefined ? undefined : { root, path: pick.candidate.name }
      if (reference === undefined) return undefined
      const label = reference.path.split('/').at(-1) ?? reference.path
      return {
        insert: {
          source: FILE_SOURCE_NAME,
          ref: encodeReference(reference),
          label,
          clipboardText: `@${reference.path}`,
        },
      }
    },
  }
}
