export const PET_FOOD_KINDS = Object.freeze(['basic', 'standard', 'premium'] as const)

export type PetFoodKind = (typeof PET_FOOD_KINDS)[number]

export interface PetFoodInventory {
  readonly basic: number
  readonly standard: number
  readonly premium: number
}

export interface PetFoodRule {
  readonly starCost: number
  readonly affinityGain: number
  readonly inventoryLimit: number
}

export interface PetEconomyRules {
  readonly starLimit: number
  readonly affinityLimit: number
  readonly conversationStartedStars: number
  readonly taskCompletedStars: number
  readonly activeUsageIntervalMs: number
  readonly activeUsageStars: number
  readonly petAffinityGain: number
  readonly petCooldownMs: number
  readonly foods: Readonly<Record<PetFoodKind, PetFoodRule>>
}

export interface PetEconomyState {
  readonly stars: number
  readonly foods: PetFoodInventory
  readonly affinity: number
  /** Lifetime active client usage. Whole reward intervals are derived from this value. */
  readonly activeUsageMs: number
  /** Reward event IDs retained solely to make reward delivery idempotent. */
  readonly rewardedEventIds: readonly string[]
  /** Caller-supplied clock value for the most recent accepted pet interaction. */
  readonly lastPetAtMs: number | null
}

export type PetEconomyEvent =
  | { readonly type: 'conversation_started'; readonly eventId: string }
  | { readonly type: 'task_completed'; readonly eventId: string }
  | { readonly type: 'active_usage_added'; readonly durationMs: number }
  | { readonly type: 'food_purchased'; readonly food: PetFoodKind; readonly quantity: number }
  | { readonly type: 'pet_fed'; readonly food: PetFoodKind }
  | { readonly type: 'pet_interacted'; readonly atMs: number }

export type PetRewardEvent = Extract<
  PetEconomyEvent,
  { readonly type: 'conversation_started' | 'task_completed' }
>

export interface PetEconomyDelta {
  readonly stars: number
  readonly foods: PetFoodInventory
  readonly affinity: number
  readonly activeUsageMs: number
}

export type PetEconomyRejection =
  | 'insufficient_stars'
  | 'inventory_full'
  | 'out_of_stock'
  | 'affinity_full'
  | 'duplicate_event'
  | 'pet_cooldown'

export type PetEconomyTransition =
  | {
      readonly accepted: true
      readonly state: PetEconomyState
      readonly delta: PetEconomyDelta
    }
  | {
      readonly accepted: false
      readonly state: PetEconomyState
      readonly delta: PetEconomyDelta
      readonly reason: PetEconomyRejection
      readonly retryAfterMs?: number
    }

/** Bounds persisted deduplication data and untrusted event identifiers. */
export const MAX_REWARDED_EVENT_IDS = 512
export const MAX_REWARD_EVENT_ID_LENGTH = 256

const EMPTY_INVENTORY: PetFoodInventory = Object.freeze({
  basic: 0,
  standard: 0,
  premium: 0,
})

const ZERO_DELTA: PetEconomyDelta = Object.freeze({
  stars: 0,
  foods: EMPTY_INVENTORY,
  affinity: 0,
  activeUsageMs: 0,
})

export const DEFAULT_PET_ECONOMY_RULES: PetEconomyRules = Object.freeze({
  starLimit: 999_999,
  affinityLimit: 100,
  conversationStartedStars: 3,
  taskCompletedStars: 5,
  activeUsageIntervalMs: 30 * 60_000,
  activeUsageStars: 2,
  petAffinityGain: 1,
  petCooldownMs: 10_000,
  foods: Object.freeze({
    basic: Object.freeze({ starCost: 5, affinityGain: 3, inventoryLimit: 99 }),
    standard: Object.freeze({ starCost: 10, affinityGain: 7, inventoryLimit: 99 }),
    premium: Object.freeze({ starCost: 18, affinityGain: 14, inventoryLimit: 99 }),
  }),
})

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function hasExactKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  const actual = Reflect.ownKeys(value)
  return actual.length === keys.length
    && actual.every((key) => typeof key === 'string' && keys.includes(key))
}

function isBoundedInteger(value: unknown, minimum: number, maximum: number): value is number {
  return typeof value === 'number'
    && Number.isSafeInteger(value)
    && value >= minimum
    && value <= maximum
}

function assertNonNegativeInteger(value: unknown, label: string): asserts value is number {
  if (!isBoundedInteger(value, 0, Number.MAX_SAFE_INTEGER)) {
    throw new RangeError(`${label} must be a non-negative safe integer`)
  }
}

function assertPositiveInteger(value: unknown, label: string): asserts value is number {
  if (!isBoundedInteger(value, 1, Number.MAX_SAFE_INTEGER)) {
    throw new RangeError(`${label} must be a positive safe integer`)
  }
}

function isFoodKind(value: unknown): value is PetFoodKind {
  return typeof value === 'string' && (PET_FOOD_KINDS as readonly string[]).includes(value)
}

function isRewardEventId(value: unknown): value is string {
  return typeof value === 'string'
    && value.trim().length > 0
    && value === value.trim()
    && value.length <= MAX_REWARD_EVENT_ID_LENGTH
}

function assertRewardEventId(value: unknown): asserts value is string {
  if (typeof value !== 'string' || value.trim().length === 0 || value !== value.trim()) {
    throw new TypeError('eventId must be a non-empty string without surrounding whitespace')
  }
  if (value.length > MAX_REWARD_EVENT_ID_LENGTH) {
    throw new RangeError(`eventId must not exceed ${MAX_REWARD_EVENT_ID_LENGTH} characters`)
  }
}

function checkedSum(left: number, right: number, label: string): number {
  const result = left + right
  if (!Number.isSafeInteger(result)) throw new RangeError(`${label} exceeds the safe integer range`)
  return result
}

function checkedProduct(left: number, right: number, label: string): number {
  if (left !== 0 && right > Math.floor(Number.MAX_SAFE_INTEGER / left)) {
    throw new RangeError(`${label} exceeds the safe integer range`)
  }
  return left * right
}

/** Validate a rule set at the runtime boundary. Invalid tuning is never silently clamped. */
export function assertPetEconomyRules(rules: PetEconomyRules): void {
  if (!isRecord(rules) || !hasExactKeys(rules, [
    'starLimit',
    'affinityLimit',
    'conversationStartedStars',
    'taskCompletedStars',
    'activeUsageIntervalMs',
    'activeUsageStars',
    'petAffinityGain',
    'petCooldownMs',
    'foods',
  ])) {
    throw new TypeError('pet economy rules have an invalid shape')
  }

  assertNonNegativeInteger(rules.starLimit, 'starLimit')
  assertNonNegativeInteger(rules.affinityLimit, 'affinityLimit')
  assertNonNegativeInteger(rules.conversationStartedStars, 'conversationStartedStars')
  assertNonNegativeInteger(rules.taskCompletedStars, 'taskCompletedStars')
  assertPositiveInteger(rules.activeUsageIntervalMs, 'activeUsageIntervalMs')
  assertNonNegativeInteger(rules.activeUsageStars, 'activeUsageStars')
  assertPositiveInteger(rules.petAffinityGain, 'petAffinityGain')
  assertNonNegativeInteger(rules.petCooldownMs, 'petCooldownMs')

  if (!isRecord(rules.foods) || !hasExactKeys(rules.foods, PET_FOOD_KINDS)) {
    throw new TypeError('foods must contain exactly the supported food kinds')
  }
  for (const kind of PET_FOOD_KINDS) {
    const food = rules.foods[kind]
    if (!isRecord(food) || !hasExactKeys(food, ['starCost', 'affinityGain', 'inventoryLimit'])) {
      throw new TypeError(`foods.${kind} has an invalid shape`)
    }
    assertNonNegativeInteger(food.starCost, `foods.${kind}.starCost`)
    assertPositiveInteger(food.affinityGain, `foods.${kind}.affinityGain`)
    assertNonNegativeInteger(food.inventoryLimit, `foods.${kind}.inventoryLimit`)
    checkedProduct(food.starCost, food.inventoryLimit, `foods.${kind} maximum cost`)
  }
}

function hasValidStateShape(value: unknown, rules: PetEconomyRules): value is PetEconomyState {
  if (!isRecord(value) || !hasExactKeys(value, [
    'stars',
    'foods',
    'affinity',
    'activeUsageMs',
    'rewardedEventIds',
    'lastPetAtMs',
  ])) return false
  if (!isBoundedInteger(value.stars, 0, rules.starLimit)) return false
  if (!isBoundedInteger(value.affinity, 0, rules.affinityLimit)) return false
  if (!isBoundedInteger(value.activeUsageMs, 0, Number.MAX_SAFE_INTEGER)) return false
  if (value.lastPetAtMs !== null) {
    if (!isBoundedInteger(value.lastPetAtMs, 0, Number.MAX_SAFE_INTEGER)) return false
    if (rules.petCooldownMs > Number.MAX_SAFE_INTEGER - value.lastPetAtMs) return false
  }
  if (!Array.isArray(value.rewardedEventIds) || value.rewardedEventIds.length > MAX_REWARDED_EVENT_IDS) return false
  const eventIds = value.rewardedEventIds as unknown[]
  if (!eventIds.every(isRewardEventId) || new Set(eventIds).size !== eventIds.length) return false
  if (!isRecord(value.foods) || !hasExactKeys(value.foods, PET_FOOD_KINDS)) return false
  const foods = value.foods
  return PET_FOOD_KINDS.every((kind) =>
    isBoundedInteger(foods[kind], 0, rules.foods[kind].inventoryLimit),
  )
}

/** Runtime guard suitable for data supplied by an outer persistence layer. */
export function isPetEconomyState(
  value: unknown,
  rules: PetEconomyRules = DEFAULT_PET_ECONOMY_RULES,
): value is PetEconomyState {
  assertPetEconomyRules(rules)
  return hasValidStateShape(value, rules)
}

/** Strictly parse and detach an externally supplied state object. */
export function parsePetEconomyState(
  value: unknown,
  rules: PetEconomyRules = DEFAULT_PET_ECONOMY_RULES,
): PetEconomyState {
  assertPetEconomyRules(rules)
  if (!hasValidStateShape(value, rules)) throw new TypeError('invalid pet economy state')
  return {
    stars: value.stars,
    foods: {
      basic: value.foods.basic,
      standard: value.foods.standard,
      premium: value.foods.premium,
    },
    affinity: value.affinity,
    activeUsageMs: value.activeUsageMs,
    rewardedEventIds: [...value.rewardedEventIds],
    lastPetAtMs: value.lastPetAtMs,
  }
}

function sanitizedInteger(value: unknown, maximum: number): number {
  if (typeof value !== 'number' || !Number.isSafeInteger(value)) return 0
  return Math.min(maximum, Math.max(0, value))
}

function sanitizedPetAt(value: unknown, cooldownMs: number): number | null {
  if (value === null) return null
  if (typeof value !== 'number' || !Number.isSafeInteger(value)) return null
  const atMs = Math.max(0, value)
  return cooldownMs <= Number.MAX_SAFE_INTEGER - atMs ? atMs : null
}

/**
 * Convert unknown loadable data to a canonical state. Numeric strings and
 * fractions are deliberately not coerced; missing/corrupt fields fall back
 * to zero while safe integers are clamped to the active rule set.
 */
export function sanitizePetEconomyState(
  value: unknown,
  rules: PetEconomyRules = DEFAULT_PET_ECONOMY_RULES,
): PetEconomyState {
  assertPetEconomyRules(rules)
  const source = isRecord(value) ? value : {}
  const foodSource = isRecord(source.foods) ? source.foods : {}
  const rawEventIds = Array.isArray(source.rewardedEventIds) ? source.rewardedEventIds : []
  const newestEventIds: string[] = []
  const seen = new Set<string>()
  for (let index = rawEventIds.length - 1; index >= 0 && newestEventIds.length < MAX_REWARDED_EVENT_IDS; index -= 1) {
    const candidate: unknown = rawEventIds[index]
    if (!isRewardEventId(candidate) || seen.has(candidate)) continue
    seen.add(candidate)
    newestEventIds.push(candidate)
  }
  newestEventIds.reverse()
  return {
    stars: sanitizedInteger(source.stars, rules.starLimit),
    foods: {
      basic: sanitizedInteger(foodSource.basic, rules.foods.basic.inventoryLimit),
      standard: sanitizedInteger(foodSource.standard, rules.foods.standard.inventoryLimit),
      premium: sanitizedInteger(foodSource.premium, rules.foods.premium.inventoryLimit),
    },
    affinity: sanitizedInteger(source.affinity, rules.affinityLimit),
    activeUsageMs: sanitizedInteger(source.activeUsageMs, Number.MAX_SAFE_INTEGER),
    rewardedEventIds: newestEventIds,
    lastPetAtMs: sanitizedPetAt(source.lastPetAtMs, rules.petCooldownMs),
  }
}

/** Alias emphasizing use at an outer persistence adapter's load boundary. */
export const loadPetEconomyState = sanitizePetEconomyState

/** Return a fresh zeroed state. Persistence is deliberately left to the caller. */
export function createPetEconomyState(): PetEconomyState {
  return {
    stars: 0,
    foods: { basic: 0, standard: 0, premium: 0 },
    affinity: 0,
    activeUsageMs: 0,
    rewardedEventIds: [],
    lastPetAtMs: null,
  }
}

function assertState(state: PetEconomyState, rules: PetEconomyRules): void {
  if (!hasValidStateShape(state, rules)) throw new TypeError('invalid pet economy state')
}

function assertEvent(event: PetEconomyEvent): void {
  if (!isRecord(event) || typeof event.type !== 'string') throw new TypeError('invalid pet economy event')
  switch (event.type) {
    case 'conversation_started':
    case 'task_completed':
      if (!hasExactKeys(event, ['type', 'eventId'])) throw new TypeError(`invalid ${event.type} event`)
      assertRewardEventId(event.eventId)
      return
    case 'active_usage_added':
      if (!hasExactKeys(event, ['type', 'durationMs'])) throw new TypeError('invalid active_usage_added event')
      assertPositiveInteger(event.durationMs, 'durationMs')
      return
    case 'food_purchased':
      if (!hasExactKeys(event, ['type', 'food', 'quantity']) || !isFoodKind(event.food)) {
        throw new TypeError('invalid food_purchased event')
      }
      assertPositiveInteger(event.quantity, 'quantity')
      return
    case 'pet_fed':
      if (!hasExactKeys(event, ['type', 'food']) || !isFoodKind(event.food)) {
        throw new TypeError('invalid pet_fed event')
      }
      return
    case 'pet_interacted':
      if (!hasExactKeys(event, ['type', 'atMs'])) throw new TypeError('invalid pet_interacted event')
      assertNonNegativeInteger(event.atMs, 'atMs')
      return
    default:
      throw new TypeError('unknown pet economy event')
  }
}

function foodDelta(kind: PetFoodKind, amount: number): PetFoodInventory {
  return {
    basic: kind === 'basic' ? amount : 0,
    standard: kind === 'standard' ? amount : 0,
    premium: kind === 'premium' ? amount : 0,
  }
}

function accepted(
  state: PetEconomyState,
  delta: PetEconomyDelta,
): PetEconomyTransition {
  return { accepted: true, state, delta }
}

function rejected(
  state: PetEconomyState,
  reason: PetEconomyRejection,
  retryAfterMs?: number,
): PetEconomyTransition {
  return retryAfterMs === undefined
    ? { accepted: false, reason, state, delta: ZERO_DELTA }
    : { accepted: false, reason, retryAfterMs, state, delta: ZERO_DELTA }
}

function appendRewardedEventId(eventIds: readonly string[], eventId: string): readonly string[] {
  const next = eventIds.length === MAX_REWARDED_EVENT_IDS
    ? eventIds.slice(1)
    : [...eventIds]
  next.push(eventId)
  return next
}

function cappedProduct(left: number, right: number, limit: number): number {
  if (left === 0 || right === 0 || limit === 0) return 0
  return left > Math.floor(limit / right) ? limit : left * right
}

/** Apply one immutable economy transition. This function has no clock, DOM, or storage dependency. */
export function applyPetEconomyEvent(
  state: PetEconomyState,
  event: PetEconomyEvent,
  rules: PetEconomyRules = DEFAULT_PET_ECONOMY_RULES,
): PetEconomyTransition {
  assertPetEconomyRules(rules)
  assertState(state, rules)
  assertEvent(event)

  if (event.type === 'conversation_started' || event.type === 'task_completed') {
    if (state.rewardedEventIds.includes(event.eventId)) return rejected(state, 'duplicate_event')
    const configuredReward = event.type === 'conversation_started'
      ? rules.conversationStartedStars
      : rules.taskCompletedStars
    const reward = Math.min(configuredReward, rules.starLimit - state.stars)
    return accepted(
      {
        ...state,
        stars: state.stars + reward,
        rewardedEventIds: appendRewardedEventId(state.rewardedEventIds, event.eventId),
      },
      { ...ZERO_DELTA, stars: reward },
    )
  }

  if (event.type === 'active_usage_added') {
    const activeUsageMs = checkedSum(state.activeUsageMs, event.durationMs, 'activeUsageMs')
    const previousIntervals = Math.floor(state.activeUsageMs / rules.activeUsageIntervalMs)
    const nextIntervals = Math.floor(activeUsageMs / rules.activeUsageIntervalMs)
    const completedIntervals = nextIntervals - previousIntervals
    const headroom = rules.starLimit - state.stars
    const starReward = cappedProduct(completedIntervals, rules.activeUsageStars, headroom)
    return accepted(
      { ...state, stars: state.stars + starReward, activeUsageMs },
      { ...ZERO_DELTA, stars: starReward, activeUsageMs: event.durationMs },
    )
  }

  if (event.type === 'food_purchased') {
    const rule = rules.foods[event.food]
    const current = state.foods[event.food]
    if (event.quantity > rule.inventoryLimit - current) return rejected(state, 'inventory_full')
    const cost = checkedProduct(rule.starCost, event.quantity, 'food purchase cost')
    if (cost > state.stars) return rejected(state, 'insufficient_stars')
    return accepted(
      {
        ...state,
        stars: state.stars - cost,
        foods: { ...state.foods, [event.food]: current + event.quantity },
      },
      { ...ZERO_DELTA, stars: -cost, foods: foodDelta(event.food, event.quantity) },
    )
  }

  if (event.type === 'pet_fed') {
    const stocked = state.foods[event.food]
    if (stocked === 0) return rejected(state, 'out_of_stock')
    if (state.affinity === rules.affinityLimit) return rejected(state, 'affinity_full')
    const affinityGain = Math.min(rules.foods[event.food].affinityGain, rules.affinityLimit - state.affinity)
    return accepted(
      {
        ...state,
        foods: { ...state.foods, [event.food]: stocked - 1 },
        affinity: state.affinity + affinityGain,
      },
      { ...ZERO_DELTA, foods: foodDelta(event.food, -1), affinity: affinityGain },
    )
  }

  if (state.lastPetAtMs !== null && rules.petCooldownMs > 0) {
    if (event.atMs < state.lastPetAtMs) {
      const clockRollbackMs = state.lastPetAtMs - event.atMs
      return rejected(
        state,
        'pet_cooldown',
        checkedSum(clockRollbackMs, rules.petCooldownMs, 'pet cooldown'),
      )
    }
    const elapsedMs = event.atMs - state.lastPetAtMs
    if (elapsedMs < rules.petCooldownMs) {
      return rejected(state, 'pet_cooldown', rules.petCooldownMs - elapsedMs)
    }
  }
  if (state.affinity === rules.affinityLimit) return rejected(state, 'affinity_full')
  if (rules.petCooldownMs > Number.MAX_SAFE_INTEGER - event.atMs) {
    throw new RangeError('atMs cannot represent the end of the pet cooldown')
  }
  const affinityGain = Math.min(rules.petAffinityGain, rules.affinityLimit - state.affinity)
  return accepted(
    { ...state, affinity: state.affinity + affinityGain, lastPetAtMs: event.atMs },
    { ...ZERO_DELTA, affinity: affinityGain },
  )
}

/** Award a caller-identified event once. Re-delivery returns duplicate_event. */
export function rewardEvent(
  state: PetEconomyState,
  event: PetRewardEvent,
  rules: PetEconomyRules = DEFAULT_PET_ECONOMY_RULES,
): PetEconomyTransition {
  if (event.type !== 'conversation_started' && event.type !== 'task_completed') {
    throw new TypeError('rewardEvent only accepts conversation_started or task_completed')
  }
  return applyPetEconomyEvent(state, event, rules)
}

export function rewardConversationStart(
  state: PetEconomyState,
  eventId: string,
  rules: PetEconomyRules = DEFAULT_PET_ECONOMY_RULES,
): PetEconomyTransition {
  return rewardEvent(state, { type: 'conversation_started', eventId }, rules)
}

export function rewardTaskCompletion(
  state: PetEconomyState,
  eventId: string,
  rules: PetEconomyRules = DEFAULT_PET_ECONOMY_RULES,
): PetEconomyTransition {
  return rewardEvent(state, { type: 'task_completed', eventId }, rules)
}

export function rewardActiveUsage(
  state: PetEconomyState,
  durationMs: number,
  rules: PetEconomyRules = DEFAULT_PET_ECONOMY_RULES,
): PetEconomyTransition {
  return applyPetEconomyEvent(state, { type: 'active_usage_added', durationMs }, rules)
}

/** Preferred integration name for incremental, already-observed active time. */
export const accrueActiveTime = rewardActiveUsage

export function purchasePetFood(
  state: PetEconomyState,
  food: PetFoodKind,
  quantity = 1,
  rules: PetEconomyRules = DEFAULT_PET_ECONOMY_RULES,
): PetEconomyTransition {
  return applyPetEconomyEvent(state, { type: 'food_purchased', food, quantity }, rules)
}

/** Concise alias for economy integrations. */
export const buyFood = purchasePetFood

export function feedPet(
  state: PetEconomyState,
  food: PetFoodKind,
  rules: PetEconomyRules = DEFAULT_PET_ECONOMY_RULES,
): PetEconomyTransition {
  return applyPetEconomyEvent(state, { type: 'pet_fed', food }, rules)
}

/** Concise alias for economy integrations. */
export const feed = feedPet

/** Apply one clock-injected pet interaction with a configurable cooldown. */
export function pet(
  state: PetEconomyState,
  atMs: number,
  rules: PetEconomyRules = DEFAULT_PET_ECONOMY_RULES,
): PetEconomyTransition {
  return applyPetEconomyEvent(state, { type: 'pet_interacted', atMs }, rules)
