 * Client-side pet image background extraction. Pure pixel logic lives here so
 * it stays testable in Node; the DOM decoding part is a thin wrapper in
 * pet-appearance.ts. Images that already carry transparency are left alone
 * (animated GIFs keep their animation); opaque images get their
 * edge-connected background removed so the pet can render without a frame.
 */

/** Longest side the extraction pipeline processes (the pet renders ≤ 256px). */
export const PET_PROCESS_MAX_DIMENSION = 1024

/** Alpha at or above this value counts as an opaque pixel. */
export const PET_OPAQUE_ALPHA = 250

/** Extraction is abandoned when fewer than this fraction of pixels were removed. */
export const PET_MIN_REMOVED_RATIO = 0.004
/** Extraction is abandoned when more than this fraction was removed (would destroy the subject). */
export const PET_MAX_REMOVED_RATIO = 0.92

export interface PetPixelBuffer {
  readonly width: number
  readonly height: number
  readonly data: Uint8ClampedArray
}

/** True when a meaningful share of pixels is transparent/semi-transparent. */
export function hasMeaningfulTransparency(
  pixels: PetPixelBuffer,
  alphaThreshold = 16,
  minRatio = 0.001,
): boolean {
  const { data, width, height } = pixels
  const total = width * height
  if (total === 0) return false
  // Sample large images so this stays a cheap pre-check.
  const step = total > 300_000 ? 4 : 1
  let transparent = 0
  let counted = 0
  for (let pixel = 0; pixel < total; pixel += step) {
    counted += 1
    if ((data[pixel * 4 + 3] ?? 0) <= alphaThreshold) transparent += 1
  }
  return transparent / counted >= minRatio
}

/**
 * Adaptive region-growing tolerance derived from the four corner patches.
 * Uniform corners (a solid backdrop) keep a tight tolerance; gradient or
 * textured corners allow a wider one so the fill still escapes the border.
 */
export function petBackgroundTolerance(pixels: PetPixelBuffer): number {
  const { data, width, height } = pixels
  const patch = 12
  const offsets = [
    [0, 0],
    [width - patch, 0],
    [0, height - patch],
    [width - patch, height - patch],
  ] as const
  const samples: number[] = []
  for (const [ox, oy] of offsets) {
    for (let y = Math.max(0, oy); y < Math.min(height, oy + patch); y += 2) {
      for (let x = Math.max(0, ox); x < Math.min(width, ox + patch); x += 2) {
        const base = (y * width + x) * 4
        if ((data[base + 3] ?? 0) < PET_OPAQUE_ALPHA) continue
        samples.push(data[base] ?? 0, data[base + 1] ?? 0, data[base + 2] ?? 0)
      }
    }
  }
  if (samples.length < 24) return 36
  let maxStdDev = 0
  for (const channel of [0, 1, 2]) {
    let sum = 0
    let squares = 0
    let count = 0
    for (let index = channel; index < samples.length; index += 3) {
      const value = samples[index] ?? 0
      sum += value
      squares += value * value
      count += 1
    }
    const mean = sum / count
    const stdDev = Math.sqrt(Math.max(0, squares / count - mean * mean))
    if (stdDev > maxStdDev) maxStdDev = stdDev
  }
  return Math.min(44, Math.max(20, Math.round(22 + maxStdDev * 1.4)))
}

/**
 * Remove the edge-connected background: a region grow seeded from every
 * border pixel, where a neighbor joins when its color distance from an
 * already-removed neighbor stays within `tolerance`. Returns a new RGBA
 * buffer whose background pixels have alpha 0. Pixels that are already
 * transparent never join the background region.
 */
export function extractPetSubject(
  pixels: PetPixelBuffer,
  tolerance = petBackgroundTolerance(pixels),
): Uint8ClampedArray {
  const { data, width, height } = pixels
  const total = width * height
  const marks = new Uint8Array(total) // 0 unknown, 2 background
  const stack = new Int32Array(total)
  let stackTop = 0
  const toleranceSquared = tolerance * tolerance

  const grow = (index: number, red: number, green: number, blue: number): void => {
    if (marks[index] !== 0) return
    const base = index * 4
    if ((data[base + 3] ?? 0) < PET_OPAQUE_ALPHA) return
    const dr = (data[base] ?? 0) - red
    const dg = (data[base + 1] ?? 0) - green
    const db = (data[base + 2] ?? 0) - blue
    if (dr * dr + dg * dg + db * db > toleranceSquared) return
    marks[index] = 2
    stack[stackTop++] = index
  }

  const seed = (index: number): void => {
    if (marks[index] !== 0) return
    const base = index * 4
    if ((data[base + 3] ?? 0) < PET_OPAQUE_ALPHA) return
    marks[index] = 2
    stack[stackTop++] = index
  }

  for (let x = 0; x < width; x += 1) {
    seed(x)
    seed((height - 1) * width + x)
  }
  for (let y = 0; y < height; y += 1) {
    seed(y * width)
    seed(y * width + width - 1)
  }

  while (stackTop > 0) {
    const index = stack[--stackTop] ?? 0
    const x = index % width
    const base = index * 4
    const red = data[base] ?? 0
    const green = data[base + 1] ?? 0
    const blue = data[base + 2] ?? 0
    if (x > 0) grow(index - 1, red, green, blue)
    if (x < width - 1) grow(index + 1, red, green, blue)
    if (index >= width) grow(index - width, red, green, blue)
    if (index < total - width) grow(index + width, red, green, blue)
  }

  const output = new Uint8ClampedArray(data.length)
  output.set(data)
  for (let index = 0; index < total; index += 1) {
    if (marks[index] !== 2) continue
    const base = index * 4
    output[base] = 0
    output[base + 1] = 0
    output[base + 2] = 0
    output[base + 3] = 0
  }
  return output
}

/** Fraction of previously opaque pixels the extraction turned transparent. */
export function backgroundRemovedRatio(pixels: PetPixelBuffer, output: Uint8ClampedArray): number {
  const total = pixels.width * pixels.height
  if (total === 0) return 0
  let removed = 0
  for (let index = 0; index < total; index += 1) {
    const base = index * 4
    if ((output[base + 3] ?? 0) === 0 && (pixels.data[base + 3] ?? 0) >= PET_OPAQUE_ALPHA) removed += 1
  }
  return removed / total
}
